from pathlib import Path
import hashlib,json,ast
base=Path('SKILLS-depo/collaborate')
p=base/'scripts/collaboration_install.py'
s=p.read_text().replace('import hashlib\n','import hashlib\nimport json\n')
tree=ast.parse((base/'scripts/collaboration_task.py').read_text())
profiles=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='OWNER_PROFILES' for t in n.targets))
pin=hashlib.sha256(json.dumps(profiles,sort_keys=True,separators=(',',':')).encode()).hexdigest()
s=s.replace("PACKAGE = '.agents/skills/collaborate'", "PACKAGE = '.agents/skills/collaborate'\n# Fixed reviewed provider declaration, independent of selected-project code.\nPROFILES_SHA256 = '"+pin+"'")
s=s.replace('    return result\n\n\ndef assess_project', "    if hashlib.sha256(json.dumps(result, sort_keys=True, separators=(',', ':')).encode()).hexdigest() != PROFILES_SHA256:\n        raise ValueError('owner-profiles-not-reviewed')\n    return result\n\n\ndef reviewed_inventory(root):\n    \"\"\"Read recorded reviewed bytes; these cooperative receipts grant no authority.\"\"\"\n    for path in ('control_records/collaboration-installation.json', 'control_records/project-setup.json'):\n        try:\n            record = json.loads(_read(root, path))\n            if record.get('project_root') != str(root):\n                continue\n            if path.endswith('collaboration-installation.json'):\n                if record.get('schema_version') == 1 and record.get('status') == 'completed':\n                    return record['package_inventory']\n            else:\n                for op in reversed(record.get('module_adoptions', [])):\n                    if op.get('module_id') == 'collaborate' and op.get('status') == 'completed':\n                        return {p: h for p, h in op['packages'][PACKAGE]['after'].items() if h != 'directory'}\n        except (OSError, ValueError, KeyError, TypeError):\n            continue\n    return None\n\n\ndef assess_project")
s=s.replace('    if expected_inventory is not None:\n', "    if expected_inventory is None:\n        expected_inventory = reviewed_inventory(root)\n    if expected_inventory is None:\n        diagnostics.append({'code': 'COLLAB_REVIEWED_INVENTORY_REQUIRED'})\n    if expected_inventory is not None:\n")
s=s.replace("if not isinstance(expected_inventory, dict) or any(not p.startswith(PACKAGE + '/') for p in expected_inventory):", "if (not isinstance(expected_inventory, dict) or not expected_inventory\n                or any(not isinstance(p, str) or not p.startswith(PACKAGE + '/')\n                       or '..' in Path(p).parts or not isinstance(h, str) or len(h) != 64\n                       for p, h in expected_inventory.items())):")
p.write_text(s)
cli=base/'scripts/collaborate.py';s=cli.read_text()
s=s.replace("parser.add_argument('--'+option,required=True)","parser.add_argument('--'+option,required=option=='project-root')",1)
s=s.replace("parser.add_argument('--generation',type=int,required=True)","parser.add_argument('--generation',type=int)")
s=s.replace("choices=['post'", "choices=['health','post'")
s=s.replace("    parser.add_argument('--payload-file')", "    parser.add_argument('--inventory-file', help='Reviewed complete project-relative package hash map for static health')\n    parser.add_argument('--payload-file')")
s=s.replace("    try:\n        c=Context", "    try:\n        if args.command == 'health':\n            from collaboration_install import assess_project\n            inventory=json.loads(Path(args.inventory_file).read_text()) if args.inventory_file else None\n            result=assess_project(args.project_root, expected_inventory=inventory)\n            print(json.dumps(result,sort_keys=True))\n            return 0 if result['enabled'] else 1\n        missing=[name for name in ('task_path','assignment','actor','execution','generation','policy_path','policy_sha256') if getattr(args,name) is None]\n        if missing: parser.error('Task operations require: '+', '.join('--'+name.replace('_','-') for name in missing))\n        if args.inventory_file: parser.error('--inventory-file is only for health')\n        c=Context")
cli.write_text(s)
(base/'README.md').write_text('''# Collaboration capability\n\nThe complete package is distributed in the neutral Sys4AI Template. Current\ninitializer create and prepare operations enable it by default after checked\nlocal adoption, including selected projects with earlier completed setup receipts.\nCustom or incompatible packages and guidance are preserved and block readiness.\n\nRun the installed helper's read-only static check:\n\n```sh\npython .agents/skills/collaborate/scripts/collaborate.py --project-root /absolute/project health\n```\n\nHealth compares the complete installed package against the completed setup-module\ninventory or explicit root adoption receipt, exact reviewed owner pins and default\nTask instructions. A reviewed inventory map may be supplied with --inventory-file.\nThis check executes no selected-project owner code and creates no Task or service.\nA missing review record is unavailable, even when files are present.\n\nThe current owner profile supports orchestration versions 1 and 2. The exact depot\nlegacy profile supports version 1 only; it preserves the installed root Task owner\nand offers no version 2 broker or current-input role acknowledgement proof.\n\nEnabled installation supplies the default collaboration habit. Each execution\nstill needs its manager's registered scoped policy, current native assignments,\ninput bindings and grants. Reading, delivery, acknowledgement, material evidence\nand canonical Task decisions remain separate. See [the skill](SKILL.md),\n[commands](references/commands.md) and [Task integration](references/task-integration.md).\n''')
print(hashlib.sha256(p.read_bytes()).hexdigest())
